import{_ as l,k as t,a6 as a,C as n,D as o,A as s,j as r,z as d}from"./chunks/framework.BZrHWrhq.js";const x=JSON.parse('{"title":"Downloading","description":"How to download the application.","frontmatter":{"title":"Downloading","page_title":"Downloading","description":"How to download the application.","nav_order":2,"mentions":["8Crafter"]},"headers":[{"level":2,"title":"Supported Operating Systems","slug":"supported-operating-systems","link":"#supported-operating-systems","children":[]},{"level":2,"title":"Architectures","slug":"architectures","link":"#architectures","children":[]},{"level":2,"title":"File Extension Guide","slug":"file-extension-guide","link":"#file-extension-guide","children":[]},{"level":2,"title":"Next","slug":"next","link":"#next","children":[]}],"relativePath":"general/downloading.md","filePath":"general/downloading.md"}'),u={name:"general/downloading.md"};function p(c,e,h,m,f,b){const i=s("Button");return r(),t("div",null,[e[1]||(e[1]=a('<p>Downloads can be found <a href="https://github.com/8Crafter-Studios/Bedrock-World-Editor/releases/latest" target="_blank" rel="noreferrer">here</a>.</p><p>The privacy policy and code signing policy can be found <a href="./general-information#privacy-policy">here</a>.</p><p>You want to find the download for your OS and CPU architecture.</p><p>Downloads with a <code class="shiki"><span>.zip</span></code> file extension are portable versions and can be run without installing.</p><p>NOTE: If you have a Mac with an Apple Silicon CPU, make sure you download the arm64 build. Otherwise if you have an older Mac with an Intel CPU, download the x86_64 build.</p><h2 id="supported-operating-systems" tabindex="-1">Supported Operating Systems <a class="header-anchor" href="#supported-operating-systems" aria-label="Permalink to &quot;Supported Operating Systems&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Support for mobile platforms is in development. <strong>Your</strong> contribution can help it arrive sooner, visit <a href="https://github.com/8Crafter-Studios/Bedrock-World-Editor/milestone/1" target="_blank" rel="noreferrer">this page</a> for more information.</p></div><p>The following operating systems are currently supported:</p><ul><li>Windows 10/11</li><li>Linux</li><li>macOS</li></ul><p>Even though iOS is not supported yet, you can still edit worlds from your iPhone/iPad without needing to transfer them to your computer. You can edit your iPhone/iPad&#39;s worlds directly from the app on your computer, you don&#39;t even need a cable, you can edit them over Wi-Fi. This does not require jailbreaking either, you can do it on any iPhone/iPad. More information can be found <a href="https://wiki.8crafter.com/bwe/advanced/editing-ios-worlds" target="_blank" rel="noreferrer">here</a>.</p><h2 id="architectures" tabindex="-1">Architectures <a class="header-anchor" href="#architectures" aria-label="Permalink to &quot;Architectures&quot;">​</a></h2><p>This lists all the names for different CPU architectures that are used in the release file names.</p><ul><li>64-bit CPU: <ul><li>x86_64</li><li>amd64</li></ul></li><li>32-bit CPU: <ul><li>ia32</li></ul></li><li>64-bit ARM CPU <ul><li>arm64</li></ul></li><li>32-bit ARM CPU: <ul><li>armv7l</li><li>armhf</li></ul></li></ul><h2 id="file-extension-guide" tabindex="-1">File Extension Guide <a class="header-anchor" href="#file-extension-guide" aria-label="Permalink to &quot;File Extension Guide&quot;">​</a></h2><p>This lists the different file extensions of the releases and what platforms they are for.</p><ul><li><code class="shiki"><span>.zip</span></code>: Portable build. <ul><li>All supported OSes have a zip build.</li><li>If you are using Linux and your Linux distro is not Debian-based, Red Hat-based, or SUSE-based then you must use the portable version.</li></ul></li><li><code class="shiki"><span>.exe</span></code>: Windows installer. <ul><li>This is for Windows 10 and Windows 11 (Windows ARM is supported, but make sure you get the arm build if it is available).</li></ul></li><li><code class="shiki"><span>.dmg</span></code>: macOS installer. <ul><li>This is for macOS.</li></ul></li><li><code class="shiki"><span>.deb</span></code>: Debian Linux installer. <ul><li>Use this if you install software with <code class="shiki"><span>apt</span></code></li><li>This is for Debian-based Linux distros. Some common Debian-based distros include: <ul><li>Ubuntu/Xubuntu/Kubuntu</li><li>Debian</li><li>Mint</li></ul></li></ul></li><li><code class="shiki"><span>.rpm</span></code>: Red Hat/SUSE Linux installer. <ul><li>Package managers include <code class="shiki"><span>yum</span></code> and <code class="shiki"><span>dnf</span></code></li><li>This is for Red Hat-based and SUSE-based Linux distros. Some common Redhat-based and SUSE-based Linux distros include: <ul><li>Fedora</li><li>Red Hat Enterprise Linux</li><li>AlmaLinux</li><li>Rocky Linux</li><li>CentOS Stream</li><li>Oracle Linux</li><li>openSUSE</li><li>SUSE Linux Enterprise Server</li></ul></li><li>The following distros also support <code class="shiki"><span>.rpm</span></code> installers (this list is non-exhaustive): <ul><li>Mageia</li><li>OpenMandriva</li><li>PCLinuxOS</li></ul></li></ul></li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2>',17)),n(i,{link:"./installing"},{default:o(()=>e[0]||(e[0]=[d("Next: Installing")])),_:1})])}const w=l(u,[["render",p]]);export{x as __pageData,w as default};
